RED_PANEL_EXTENSION = r"""
<style>
#view-admin-red{background:#0a0a0a;color:#f5f5f5;min-height:100vh}.red-shell{max-width:1600px;margin:0 auto;padding-bottom:40px}.red-shell .small,.red-shell .label,.red-shell .muted{color:#b9b9b9}.red-shell .btn{background:#0a0a0a;color:#fff;border:1px solid #666}.red-shell .btn:hover{background:#fff;color:#000}.red-targetbar{display:grid;grid-template-columns:minmax(260px,520px) 220px 220px;gap:8px}.red-targetbar input{height:38px;border:1px solid #777;background:#111;color:#fff;padding:0 12px;font:13px Consolas,monospace}.red-banner{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(320px,.5fr);gap:14px;margin:14px 0}.red-threat-card{border:1px solid #777;background:#111;padding:18px;min-height:150px}.red-threat-title{font:700 34px/1 Arial,Helvetica,sans-serif;letter-spacing:-.03em}.red-threat-sub{margin-top:8px;color:#aaa;font:11px/1.5 Arial,Helvetica,sans-serif}.red-score-grid{display:grid;grid-template-columns:repeat(3,1fr);border-left:1px solid #555;border-top:1px solid #555}.red-score-grid>div{padding:12px;border-right:1px solid #555;border-bottom:1px solid #555}.red-score-grid strong{display:block;font-size:28px;margin-top:5px}.red-meter{height:8px;background:#222;margin-top:9px;position:relative}.red-meter>span{display:block;height:100%;background:#fff}.red-hero{display:grid;grid-template-columns:repeat(5,1fr);border-left:1px solid #555;border-top:1px solid #555;margin:14px 0}.red-hero>div{padding:11px;border-right:1px solid #555;border-bottom:1px solid #555}.red-hero strong{display:block;font-size:18px;margin-top:4px}.red-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:14px}.red-panel{border:1px solid #555;background:#0f0f0f;padding:14px}.red-row{padding:8px 0;border-bottom:1px solid #2f2f2f;font-size:10px;line-height:1.45}.red-row:last-child{border-bottom:0}.red-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.red-graph{height:430px;border:1px solid #444;background:#050505;overflow:hidden}.red-graph svg{width:100%;height:100%;display:block}.red-node circle{fill:#0a0a0a;stroke:#fff;stroke-width:1.5}.red-node.target circle{fill:#fff}.red-node.target text{fill:#000}.red-node text{fill:#fff;font:9px Consolas,monospace}.red-edge{stroke:#6e6e6e;stroke-width:1}.red-edge.hot{stroke:#fff;stroke-width:2}.red-plan-step{display:grid;grid-template-columns:34px 1fr;gap:10px;padding:10px 0;border-bottom:1px solid #2b2b2b}.red-plan-step:last-child{border-bottom:0}.red-plan-num{width:30px;height:30px;border:1px solid #aaa;display:grid;place-items:center;font-weight:700}.red-kicker{font:700 9px Arial,Helvetica,sans-serif;letter-spacing:.18em;color:#aaa}.red-warning{border:1px solid #888;padding:10px 12px;margin-top:12px;font:10px/1.5 Arial,Helvetica,sans-serif;background:#151515}.red-shell .sectionhead{border-bottom-color:#555}.red-shell h2,.red-shell h3{color:#fff}@media(max-width:1050px){.red-grid,.red-banner{grid-template-columns:1fr}.red-hero,.red-score-grid{grid-template-columns:1fr 1fr}.red-targetbar{grid-template-columns:1fr}.red-graph{height:360px}}
</style>
<script>
(()=>{
const R=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function token(){return sessionStorage.getItem('campusOpsAdminToken')||''}
function inject(){if(R('view-admin-red'))return;const nav=document.querySelector('nav'),main=document.querySelector('main'),foot=main?.querySelector('.foot');if(!nav||!main||typeof pages==='undefined')return;pages['admin-red']=['Red Panel','Adversary emulation command workspace.'];const b=document.createElement('button');b.className='tab admin-tab show';b.dataset.view='admin-red';b.textContent='RED-PANEL';b.onclick=()=>setView('admin-red');nav.appendChild(b);const v=document.createElement('div');v.className='view';v.id='view-admin-red';v.innerHTML=`<section class="red-shell"><div class="sectionhead"><div><div class="red-kicker">AUTHORIZED ADVERSARY EMULATION</div><h2 style="font-size:28px;margin-top:5px">RED-PANEL</h2><div class="small">Attack-surface intelligence, blast-radius estimation, attack-path visualization and evidence-backed validation.</div></div></div><div class="red-targetbar"><input id="redTarget" placeholder="Target IP"><button class="btn" id="redLoad">BUILD TARGET MODEL</button><button class="btn" id="redInvestigate">OPEN INVESTIGATION</button></div><div class="message" id="redMessage" style="margin-top:8px"></div><div class="red-banner"><div class="red-threat-card"><div class="red-kicker">TARGET POSTURE</div><div class="red-threat-title" id="redThreatTitle">NO TARGET LOADED</div><div class="red-threat-sub" id="redThreatSub">Select an observed asset to generate the adversary-emulation model.</div><div class="red-warning">This workspace validates exposure and likely attack paths. It does not auto-exploit, brute-force credentials, or execute destructive actions.</div></div><div class="red-score-grid" id="redScoreGrid"></div></div><div class="red-hero" id="redHero"></div><div class="red-grid"><div class="red-panel"><div class="label">ATTACK-PATH GRAPH</div><div class="red-graph"><svg id="redGraph" viewBox="0 0 900 430"></svg></div></div><div class="red-panel"><div class="label">ADVERSARY HYPOTHESES</div><div id="redHypotheses"></div><div class="label" style="margin-top:16px">VALIDATION PLAN</div><div id="redPlan"></div></div></div><div class="red-grid" style="margin-top:14px"><div class="red-panel"><div class="label">OBSERVED ATTACK SURFACE</div><div id="redExposure"></div></div><div class="red-panel"><div class="label">TOP PEERS / REACH</div><div id="redPeers"></div><div class="label" style="margin-top:16px">CONTROL ACTIONS</div><div class="red-actions"><button class="btn" id="redForensics">FORENSICS</button><button class="btn" id="redContain">CONTAINMENT</button><button class="btn" id="redReload">REFRESH MODEL</button></div></div></div></section>`;main.insertBefore(v,foot||null);R('redLoad').onclick=load;R('redReload').onclick=load;R('redInvestigate').onclick=()=>pivot('investigation');R('redForensics').onclick=()=>pivot('admin-forensics');R('redContain').onclick=()=>pivot('admin-contain');R('redTarget').addEventListener('keydown',e=>{if(e.key==='Enter')load()})}
function current(){return (R('redTarget')?.value||'').trim()}
function pivot(view){const t=current();if(!t)return;if(view==='investigation'&&typeof window.openInvestigation==='function'){window.openInvestigation(t);return}if(view==='admin-forensics'){const x=R('adminForensicTarget');if(x)x.value=t}if(view==='admin-contain'){const x=R('adminContainTarget');if(x)x.value=t}try{setView(view)}catch{}}
async function load(){const t=current();if(!t)return;R('redMessage').textContent='Building target model from current-session evidence...';try{const r=await fetch('/api/v1/admin/red-panel/'+encodeURIComponent(t),{cache:'no-store',headers:{'X-Campus-Admin':token()}}),d=await r.json();if(!r.ok)throw new Error(d.detail||`HTTP ${r.status}`);render(d);R('redMessage').textContent='Target model loaded from current-session evidence.'}catch(e){R('redMessage').textContent=e.message}}
function render(d){const risk=Number(d.risk_score||0),conf=Number(d.confidence||0),blast=Number(d.blast_radius||0);R('redThreatTitle').textContent=`${d.target} · ${risk>=70?'HIGH EXPOSURE':risk>=40?'ELEVATED EXPOSURE':'CONTROLLED EXPOSURE'}`;R('redThreatSub').textContent=`${d.peer_count||0} peers · ${d.observed_flows||0} flows · ${d.security_signals||0} security signals · ${d.managed_endpoint?'managed endpoint':'unmanaged / passive visibility'}`;R('redScoreGrid').innerHTML=[['RISK',risk],['CONFIDENCE',conf],['BLAST RADIUS',blast]].map(x=>`<div><div class="label">${x[0]}</div><strong>${x[1]}</strong><div class="red-meter"><span style="width:${Math.min(100,Math.max(0,x[1]))}%"></span></div></div>`).join('');R('redHero').innerHTML=[['Target',d.target],['Flows',d.observed_flows||0],['Peers',d.peer_count||0],['Signals',d.security_signals||0],['Managed',d.managed_endpoint?'YES':'NO']].map(x=>`<div><div class="label">${esc(x[0])}</div><strong>${esc(x[1])}</strong></div>`).join('');R('redExposure').innerHTML=(d.exposures||[]).map(x=>`<div class="red-row"><b>${esc(x.port)} · ${esc(x.service_hint)}</b><br>${esc(x.flow_count)} observed flow(s)${x.administrative?' · administrative service':''}${x.high_value?' · high-value protocol':''}</div>`).join('')||'<div class="muted">No service exposure can be established from current telemetry.</div>';R('redHypotheses').innerHTML=(d.hypotheses||[]).map(x=>`<div class="red-row"><b>${esc(x.area)}</b><br>${esc(x.finding)}</div>`).join('');R('redPeers').innerHTML=(d.top_peers||[]).map(x=>`<div class="red-row"><b>${esc(x[0])}</b> · ${esc(x[1])} observed relationship(s)</div>`).join('')||'<div class="muted">No peers observed.</div>';R('redPlan').innerHTML=(d.validation_plan||[]).map(x=>`<div class="red-plan-step"><div class="red-plan-num">${esc(x.phase)}</div><div><b>${esc(x.name)}</b><br><span class="small">${esc(x.action)}</span></div></div>`).join('');renderGraph(d.attack_path||{})}
function renderGraph(g){const svg=R('redGraph');if(!svg)return;const nodes=g.nodes||[],edges=g.edges||[];if(!nodes.length){svg.innerHTML='<text x="30" y="50" fill="#aaa" font-size="12">No attack-path evidence available.</text>';return}const target=nodes.find(n=>n.kind==='TARGET')||nodes[0],peers=nodes.filter(n=>n.kind==='PEER').slice(0,10),services=nodes.filter(n=>n.kind==='SERVICE').slice(0,10);const pos={};pos[target.id]={x:450,y:215};peers.forEach((n,i)=>{const a=(-Math.PI/2)+(i/Math.max(1,peers.length))*Math.PI*2;pos[n.id]={x:450+Math.cos(a)*260,y:215+Math.sin(a)*145}});services.forEach((n,i)=>{const a=(-Math.PI/2)+(i/Math.max(1,services.length))*Math.PI*2;pos[n.id]={x:450+Math.cos(a)*150,y:215+Math.sin(a)*90}});const line=edges.map((e,i)=>{const a=pos[e.source],b=pos[e.target];if(!a||!b)return'';return`<line class="red-edge ${i<8?'hot':''}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"></line>`}).join('');const nhtml=nodes.filter(n=>pos[n.id]).map(n=>{const p=pos[n.id],t=n.kind==='TARGET'?'target':'';return`<g class="red-node ${t}" transform="translate(${p.x},${p.y})"><circle r="${n.kind==='TARGET'?32:18}"></circle><text text-anchor="middle" y="3">${esc(String(n.label||n.id).slice(0,22))}</text></g>`}).join('');svg.innerHTML=line+nhtml}
function tick(){inject();const b=document.querySelector('.tab[data-view="admin-red"]');if(b)b.style.display=token()?'block':'none'}tick();setInterval(tick,1200);
})();
</script>
"""
